 "content": "from collections import deque

def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            out.append((color, cells))
    return out

def canon(cells):
    pts = [(r, c) for r, c in cells]
    variants = []
    for flip in (1, -1):
        for k in range(4):
            arr = []
            for r, c in pts:
                x, y = r, c * flip
                for _ in range(k):
                    x, y = y, -x
                arr.append((x, y))
            mr = min(x for x, y in arr)
            mc = min(y for x, y in arr)
            variants.append(tuple(sorted((x-mr, y-mc) for x, y in arr)))
    return min(variants)

def transform(grid):
    objs = components(grid)
    refs = {canon(cells) for color, cells in objs if color == 8}
    out = [row[:] for row in grid]
    for color, cells in objs:
        if color != 8 and canon(cells) in refs:
            for r, c in cells:
                out[r][c] = 8
    return out
